package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;
public class StoreScreens extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private Activity launch(String name){return startActivitySync(new Intent().setClassName(getTargetContext(),"app.layan.quran."+name).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 private void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
 private String text(View v){String s=v instanceof TextView?((TextView)v).getText().toString()+"\n":"";if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s+=text(((ViewGroup)v).getChildAt(i));return s;}
 private void call(Activity a,String name){ui(()->{try{Method m=a.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(a);}catch(Exception e){throw new RuntimeException(e);}});}
 private void shot(Activity a,String name)throws Exception{SystemClock.sleep(1200);Bitmap b=NativeScreens.capture(this,a);File dir=getTargetContext().getExternalFilesDir("tests");dir.mkdirs();try(FileOutputStream f=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();Bundle s=new Bundle();s.putString("captured",name);sendStatus(1,s);}
 private <T extends View>T find(View v,Class<T> c){if(c.isInstance(v))return c.cast(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){T found=find(((ViewGroup)v).getChildAt(i),c);if(found!=null)return found;}return null;}
 public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();android.preference.PreferenceManager.getDefaultSharedPreferences(c).edit().putBoolean("nightMode",false).putBoolean("useArabicNames",true).commit();c.getSharedPreferences("layan_local",0).edit().putLong("prayer_lat",Double.doubleToLongBits(30.0444)).putLong("prayer_lon",Double.doubleToLongBits(31.2357)).putLong("prayer_location_time",System.currentTimeMillis()).putFloat("prayer_accuracy",30).putString("lp_location_name","القاهرة").commit();c.getSharedPreferences("layan_qibla",0).edit().putBoolean("calib_intro_shown",true).putBoolean("location_asked",true).commit();
 Activity q=launch("VerseReadingActivity");long end=SystemClock.elapsedRealtime()+90000;while(SystemClock.elapsedRealtime()<end){ListView l=q.findViewById(0x4c590102);if(l!=null&&l.getCount()==7&&l.getChildCount()>0)break;SystemClock.sleep(250);}ListView verses=q.findViewById(0x4c590102);if(verses==null||verses.getCount()!=7)throw new AssertionError("Actual Quran not ready");shot(q,"01-quran");ui(q::finish);
 Activity p=launch("PrayerActivity");Field next=p.getClass().getDeclaredField("next");next.setAccessible(true);end=SystemClock.elapsedRealtime()+120000;while(next.get(p)==null&&SystemClock.elapsedRealtime()<end)SystemClock.sleep(250);if(next.get(p)==null)throw new AssertionError("Actual prayer table not ready");shot(p,"02-prayer-times");call(p,"calculationSettings");shot(p,"05-calculation-settings");call(p,"manualCorrections");shot(p,"06-manual-prayer-times");
 ui(()->{for(View v:android.view.inspector.WindowInspector.getGlobalWindowViews())if(v.isShown()){ListView l=find(v,ListView.class);if(l!=null&&l.getCount()==8){l.performItemClick(l.getChildAt(0),0,l.getAdapter().getItemId(0));return;}}throw new AssertionError("Actual manual-correction list missing");});SystemClock.sleep(600);ui(()->{for(View v:android.view.inspector.WindowInspector.getGlobalWindowViews())if(v.isShown()){EditText input=find(v,EditText.class);if(input!=null){input.setText("3");((android.view.inputmethod.InputMethodManager)c.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(input.getWindowToken(),0);return;}}throw new AssertionError("Actual minutes editor missing");});shot(p,"07-edit-prayer-minutes");ui(p::finish);
 Activity kibla=launch("QiblaActivity");SystemClock.sleep(3500);shot(kibla,"03-qibla");ui(kibla::finish);Activity h=launch("HadithActivity");shot(h,"04-hadith");ui(h::finish);
 android.preference.PreferenceManager.getDefaultSharedPreferences(c).edit().putBoolean("nightMode",true).commit();q=launch("VerseReadingActivity");SystemClock.sleep(2500);shot(q,"08-quran-night");Activity last=q;ui(last::finish);out.putString("result","PASS 8 actual native app screens; manual-correction list and real minutes editor captured; no product modification");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
}
